public class Main{public static void main(String[] args)throws Exception{Gson gson=new Gson();BufferedReader r=new BufferedReader(new InputStreamReader(System.in));String line;while((line=r.readLine())!=null){JsonObject input=JsonParser.parseString(line).getAsJsonObject();CoverageSet object=null;JsonArray out=new JsonArray();for(JsonElement e:input.getAsJsonArray("operations")){JsonObject operation=e.getAsJsonObject();String name=operation.get("op").getAsString();if(name.equals("constructor")){if(object!=null)throw new IllegalArgumentException("Repeated constructor");object=new CoverageSet();out.add(JsonNull.INSTANCE);}else if(name.equals("put")){if(object==null)throw new IllegalArgumentException("Constructor required");object.put(operation.getAsJsonArray("args").get(0).getAsInt(),operation.getAsJsonArray("args").get(1).getAsInt(),operation.getAsJsonArray("args").get(2).getAsInt());out.add(JsonNull.INSTANCE);}else if(name.equals("remove")){if(object==null)throw new IllegalArgumentException("Constructor required");object.remove(operation.getAsJsonArray("args").get(0).getAsInt());out.add(JsonNull.INSTANCE);}else if(name.equals("covered")){if(object==null)throw new IllegalArgumentException("Constructor required");out.add(gson.toJsonTree(object.covered()));}else throw new IllegalArgumentException("Unapproved operation");}System.out.println(gson.toJson(out));}}}
